// Act V · the column of snow above the Tower is a door. Ardaël comes down it. The three voices of the Door (sing all
// the names, wear the crown, keep the register) and what each companion can give make the seven endings:
// porte (all the names sung, the forgotten come home), roi (the child wears the crown), frere (the Sans-Nom wears it),
// degel (Ardaël lets go and the Door melts), cendres (both registers burned), gardien (the child keeps the Book, honestly),
// cession (the pen is left to write). Then the epilogue, read from the flags of the whole book.
var A = { act: "V", noLead: true };
function P(o) { return Object.assign({}, A, o); }
function fin(id) { return { flag: ["fin:" + id, "acte5:fin"], ep: ["histoire", 15000] }; }
var RENDUS3 = { all: [{ has: "proces:tour=rendu" }, { has: "proces:plume=rendu" }, { has: "proces:cerf=rendu" }] };
module.exports = {
  V_p_colonne: P({ title: "La colonne", place: "pallanche",
    text: [
      "La colonne blanche monte du Grand Livre, droite, silencieuse. En levant la tête, tu vois qu'elle ne monte pas vers le ciel. Elle monte vers une porte. Très haut, au bout de la colonne, une porte de pierre noire couverte de noms, grande ouverte, sans mur de part et d'autre. La Porte des Cendres. Tout ce qu'on cède cette nuit y entre.",
      "Et quelqu'un en descend. Lentement, marche après marche, sur une colonne de neige qui ne porterait pas un oiseau. Un homme très grand, couronné de givre, qui fond et se refait, goutte à goutte.",
      "Ardaël pose le pied sur le parquet du cabinet. Il regarde le feu, la plume qui écrit, le Grand Livre. Il te regarde.",
      { before: "mordace:fin=cede", text: "« Je n'ai jamais quitté Valcendre, dit-il. Trois cent douze ans. Il fallait que la porte soit grande ouverte pour que je puisse sortir. Merci à cet homme. » Il ne regarde pas Mordace. « Maintenant, mon fils, elle va se refermer, ou ne plus jamais se refermer. Ça dépend de qui la tient. »" },
      { after: "mordace:fin=cede", text: "« Je n'ai jamais quitté Valcendre, dit-il. Trois cent douze ans. Il fallait que la porte soit grande ouverte pour que je puisse sortir. Merci à l'homme qui écrivait ici. » Il ne regarde pas l'escalier. « Maintenant, mon fils, elle va se refermer, ou ne plus jamais se refermer. Ça dépend de qui la tient. »" },
    ],
    choices: [{ label: "« Dis-moi. »", to: "V_p_choix" }] }),

  V_p_choix: P({ title: "Les trois voix", place: "pallanche",
    text: [
      "« Qui chante tous les noms l'ouvre, pour tous, dit Ardaël. Qui porte la couronne la tient fermée. Qui garde le livre la ferme d'en haut. Il y a d'autres façons. Il y en a toujours. Mais celles-là, je les connais. »",
      { with: "sansnom", text: "Ton frère s'est avancé à côté de toi. Il ne dit rien. Il regarde la couronne." },
      { if: { has: "ame:maera" }, text: "Une voix, derrière, dans l'escalier. Maëra. Elle a monté les six étages, son fuseau à la ceinture. Ardaël se fige." },
      { if: { item: "registre_anselin" }, text: "Le registre d'Anselin pèse sous ton bras. Le feu, dans la cheminée, est énorme." },
      "Derrière toi, ceux qui sont venus jusqu'ici attendent. La plume écrit. La neige monte.",
    ],
    choices: [
      { label: "Chanter tous les noms, et ouvrir la porte pour tous", if: { any: [{ has: "aelan:dit_les_noms" }, { item: "registre_anselin" }] }, why: "Tu ne connais pas tous les noms. Il faudrait le registre d'Anselin.", to: "V_f_porte", big: true },
      { label: "Prendre la couronne", to: "V_f_roi" },
      { label: "Laisser ton frère prendre la couronne", if: { all: [{ present: "sansnom" }, { conf: "sansnom", min: 50 }] }, why: "Il ne te le demandera pas, et tu ne peux pas le lui demander.", hide: { not: { present: "sansnom" } }, to: "V_f_frere" },
      { label: "Demander à ton père de lâcher la porte, et de rentrer avec les siens", if: { all: [{ has: "lisse:paix" }, { any: [{ has: "ame:maera" }, RENDUS3] }] }, why: "Il ne te croira pas. Il faudrait qu'il voie que là-haut, on sait se souvenir.", to: "V_f_degel" },
      { label: "Jeter les deux registres au feu", if: { item: "registre_anselin" }, why: "Le registre d'Anselin est resté au caveau.", hide: { not: { item: "registre_anselin" } }, to: "V_f_cendres" },
      { label: "Prendre la plume, et garder le livre. Honnêtement", to: "V_f_gardien" },
      { label: "Ne rien faire. Laisser la plume écrire", to: "V_f_cession" },
    ] }),

  V_f_porte: P({ title: "Tous les noms", place: "pallanche",
    fx: fin("porte"),
    text: [
      "Tu ouvres la bouche, et tu commences par le premier. Celui qu'Anselin a écrit en premier, dans la grange, le premier prisonnier de la file.",
      { with: "corbe", text: "Corbe reprend après toi, sur l'air du chant des morts, avec son tambour." },
      { with: "lisandre", text: "Lisandre chante avec toi, de sa voix rauque, et la cage de l'escalier la fait résonner jusqu'à la place." },
      { with: "linette", if: { item: "registre_anselin" }, text: "Linette lit les noms par-dessus ton épaule, plus vite que toi, et te souffle les suivants." },
      "Sur la place, dans la queue, quelqu'un reprend un nom. Puis cent. Les gens du Grand Livre, qui n'ont plus de souvenirs à eux, chantent ceux des autres, ceux qui leur arrivent par la colonne, et la neige s'arrête de monter. Elle redescend.",
      "Au dernier nom, tu ne t'arrêtes pas, cette fois.",
      "La porte, là-haut, s'ouvre jusqu'au bout. Et ils descendent. Par la colonne, par les toits, par les rues. Les marcheurs de la plaine blanche, les gens de Bourdonne, de Valcendre, d'Ellerune, les trois cents de Lisse, Sauvelune entière, les morts et les oubliés de trois siècles, qui rentrent chez eux. Ils se répandent dans la ville et dans le royaume comme une marée qui monte, et chacun cherche quelqu'un, et chacun trouve.",
      "Ardaël te regarde. Il ôte sa couronne. Elle fond dans ses mains. « Voilà, dit-il. Le monde va être lourd. » Il sourit. « Il va être vrai. »",
    ],
    choices: [{ label: "L'aube", to: "Z5_epilogue" }] }),

  V_f_roi: P({ title: "La couronne", place: "pallanche",
    fx: fin("roi"),
    text: [
      "Tu tends la main. Ardaël te regarde longtemps, et tu vois qu'il est soulagé, et qu'il a honte de l'être.",
      "Il ôte la couronne. Elle fond et se refait entre ses doigts. Il la pose sur ta tête.",
      "Le froid te prend au front, puis tout le corps, puis il n'y a plus de froid. Tu sens la porte. Tu la sens comme on sent une main. Elle est grande ouverte, et lourde, et tu la fermes. Lentement. Ça prend toute la nuit, et toute ta force, et sur la place la neige cesse de monter, et dans le Grand Livre la plume s'arrête au milieu d'un mot.",
      { if: { souv: "enfant:reve" }, text: "Tu entends, très loin, la voix qui chantait dans ton rêve d'enfant. Tu comprends que c'était la tienne, plus tard. Que c'est maintenant." },
      "À l'aube, tu montes la colonne. Ardaël marche à côté de toi jusqu'à la porte, et là, il s'arrête, et il passe de l'autre côté, vers la lumière jaune, vers le monde, en homme. Toi, tu restes. Tu es le Roi-Hiver. Tu tiens la porte. Tu n'as pas froid.",
    ],
    choices: [{ label: "L'aube", to: "Z5_epilogue" }] }),

  V_f_frere: P({ title: "Le frère", place: "pallanche",
    fx: fin("frere"),
    text: [
      "Tu ne dis rien. Tu regardes ton frère. Il a compris avant toi.",
      "« Là-haut, ils t'ont gardé vingt ans, dit-il. Moi, ils m'oublient entre deux portes. Il est temps que ça serve à quelque chose. » Il s'avance vers son père. « Donne-la-moi. »",
      "Ardaël le regarde comme on regarde quelqu'un qu'on n'a jamais vu. Peut-être que c'est vrai. Il lui pose la couronne sur la tête.",
      "Ton frère ferme la porte. Toute la nuit. Il a le visage d'un garçon qui porte quelque chose de trop lourd et qui ne le posera pas. À l'aube, il monte la colonne, seul. Il se retourne une fois, en haut, et lève la main.",
      { if: { any: [{ has: "ame:sansnom" }, { has: "sansnom:page" }] }, text: "Et tu sais, en le regardant, qu'en bas, dans le monde, on se souviendra de lui. Il y a une page, quelque part, avec son nom. Il y a toi." },
    ],
    choices: [{ label: "L'aube", to: "Z5_epilogue" }] }),

  V_f_degel: P({ title: "Le dégel", place: "pallanche",
    fx: fin("degel"),
    text: [
      "« Lâche-la », dis-tu.",
      "Ardaël rit, sans joie. « Et qui la tiendra ? »",
      "« Personne. Là-haut, on sait se souvenir, maintenant. Sur la Lisse, deux armées l'ont fait ensemble. Ta couronne n'a plus rien à retenir. »",
      { if: { has: "ame:maera" }, text: "Maëra traverse la pièce. Elle prend la couronne sur la tête d'Ardaël, à deux mains, comme on prend un chaudron chaud. Elle la tient. Elle la regarde fondre. « Trois cents ans, dit-elle. Ça suffit. Viens voir le soleil. »" },
      { if: { not: { has: "ame:maera" } }, text: "Tu lui racontes la reine qui a rêvé de son ancêtre, la capitaine qui a raconté son pont, les cinq maisons qui savent, maintenant. Il écoute. À la fin, il ôte la couronne lui-même." },
      "La couronne fond. Elle ne se refait pas. La colonne de neige, au-dessus de la tour, se met à fondre aussi, de haut en bas, en pluie tiède. La porte, là-haut, n'est plus une porte : c'est un passage, une arche sans battant, que plus rien ne ferme.",
      "Les oubliés descendent. Pas d'un coup : quand ils veulent, comme on rentre de voyage. Ardaël descend l'escalier de la tour, et sort sur la place, et il lève le visage vers la pluie.",
    ],
    choices: [{ label: "L'aube", to: "Z5_epilogue" }] }),

  V_f_cendres: P({ title: "Les cendres", place: "pallanche",
    fx: { flag: ["fin:cendres", "acte5:fin"], drop: "registre_anselin", ep: ["histoire", 15000] },
    text: [
      "Tu prends le registre d'Anselin. Tu prends le Grand Livre, et la plume avec. Tu les jettes au feu, les deux, l'un sur l'autre.",
      "Ardaël crie. C'est la seule fois que tu l'entends crier.",
      "Le feu les prend comme de la paille. Les noms barrés se tordent dans les flammes, des milliers, et montent par la cheminée en étincelles. Le Grand Livre brûle plus lentement : il est plein. Toute la nuit.",
      "Au matin, il n'y a plus de livre. Plus de pacte. Plus de digue. On ne peut plus vendre l'oubli : il n'y a plus de registre pour l'écrire. On ne peut plus rien céder. La neige blanche s'arrête, partout, et ne reviendra pas.",
      "Et les Orsans, les noms d'Anselin, sont partis en fumée par la cheminée de la tour. Personne ne pourra plus les chanter. Valcendre, là-bas, au bout du blanc, s'éteint doucement, comme une ville qui s'endort.",
      "Ardaël te regarde. « Tu as fait ce que les fondateurs n'ont pas osé, dit-il. Tu as fini le travail. » Il remonte la colonne, qui fond sous ses pas. Tu ne sais pas si c'est un reproche.",
    ],
    choices: [{ label: "L'aube", to: "Z5_epilogue" }] }),

  V_f_gardien: P({ title: "Le gardien", place: "pallanche",
    fx: fin("gardien"),
    text: [
      "Tu prends la plume. Elle arrête d'écrire toute seule dès que ta main se referme dessus.",
      "Tu tournes les pages du Grand Livre en arrière. Toutes les cessions de la nuit. Et à chacune, tu barres la formule, *cédé pour la paix de tous*, et tu écris à côté : *rendu.* Ça prend des jours. Des semaines.",
      { with: "linette", after: "mordace:aide", text: "Tu n'es pas seul. Linette tient l'encrier. Mordace tourne les pages, sans un mot, et te montre celles que tu oublierais." },
      { with: "linette", before: "mordace:aide", text: "Tu n'es pas seul. Linette tient l'encrier, et te montre les pages que tu oublierais." },
      { without: "linette", after: "mordace:aide", text: "Tu n'es pas seul. Mordace tourne les pages, sans un mot, et te montre celles que tu oublierais." },
      "À la fin, il reste le livre, et toi, et la porte, là-haut, à demi ouverte. Ardaël te regarde.",
      "« Quelqu'un des deux côtés doit le garder, dis-tu. Pas pour vendre. Pour que personne ne le vende. »",
      "Il hoche la tête. Il remonte la colonne. Il tiendra la porte encore un peu, et toi, tu tiendras le livre. Tu es Greffier-Majeur de la Chancellerie des Noms, et la première chose que tu fais, c'est fermer le Bureau des Cessions.",
    ],
    choices: [{ label: "L'aube", to: "Z5_epilogue" }] }),

  V_f_cession: P({ title: "La grande cession", place: "pallanche",
    fx: fin("cession"),
    text: [
      "Tu ne fais rien. Tu regardes la plume écrire.",
      "Elle écrit toute la nuit. À l'aube, elle s'arrête, parce qu'il n'y a plus rien à céder. La colonne retombe en neige fine sur tout le royaume, et la neige fond, enfin, sous un soleil de juillet.",
      "Le monde se réveille. Personne n'a mal. Personne n'a honte. Personne ne se souvient de rien qui pèse. Les gens de la queue rentrent chez eux en souriant. Les deux armées de la Lisse rentrent chez elles. Il n'y a plus de pont de Lisse, plus de vallée des Cendres, plus de fondateurs, plus de guerre d'avant. Il n'y a jamais eu de neige.",
      "Ardaël remonte la colonne avant qu'elle tombe. Il ne dit rien. Il n'a plus rien à tenir : plus personne, en haut, ne garde rien qui vaille d'être oublié.",
      "Toi, tu te souviens de tout. La neige glisse sur toi. Elle a toujours glissé.",
    ],
    choices: [{ label: "L'aube", to: "Z5_epilogue" }] }),

  Z5_epilogue: P({ title: "Après", place: null,
    text: [
      { if: { has: "fin:porte" }, text: "Le monde est plein. Les villes ont doublé en une nuit. Des gens d'il y a trois siècles apprennent à se servir d'une fourchette. Il faudra des années pour que chacun trouve sa place. Personne ne demande plus jamais à céder quoi que ce soit." },
      { if: { has: "fin:roi" }, text: "Là-haut, au bout du blanc, à Valcendre, il y a un roi jeune qui chante les noms chaque matin, et une porte qui tient. Il ne neige plus. Une fois par an, à la fête des foins, à Sauvelune, quelqu'un met une assiette de plus." },
      { if: { has: "fin:frere" }, text: "Là-haut, il y a un roi de vingt ans qui tient la porte, et en bas, il y a des gens qui se souviennent de lui. Ça lui suffit. Il l'a dit." },
      { if: { has: "fin:degel" }, text: "La porte n'est plus une porte. On va et on vient. Les morts de la vallée des Cendres ont reconstruit Valcendre, la vraie, au bord de la rivière, avec des tours fines, et la margrave de Corvanne et la reine d'Esquarre sont venues ensemble à la première fête." },
      { if: { has: "fin:cendres" }, text: "On ne vend plus l'oubli. On ne peut plus. Les gens oublient tout seuls, mal, au hasard, comme avant, comme toujours. Personne ne sait plus qu'il y a eu des Orsans. Toi, tu le sais. Tu chantes ce que tu te rappelles, et ce n'est pas tout." },
      { if: { has: "fin:gardien" }, text: "La Chancellerie des Noms ne cède plus rien. Elle garde, et elle rend. On y vient pour retrouver ce qu'on a perdu, et la queue fait trois fois le tour de la place aux Clercs, tous les jours, et ce sont des gens qui repartent en pleurant, et qui reviennent." },
      { if: { has: "fin:cession" }, text: "Le monde est léger. Tu es le seul à le trouver trop léger." },
      { with: "ysolde", text: "Ysolde rend son épée à la reine, et sa croix d'argent avec. Elle reconstruit le vieux pont de Lisse, à la main, avec ses quarante hommes, à côté du neuf. On lui demande pourquoi deux ponts. Elle dit : « Pour qu'on se souvienne qu'il y en avait un. »" },
      { if: { all: [{ present: "pie" }, { present: "linette" }] }, text: "Pie et Linette ouvrent une boutique, à Pallanche, rue des Teinturiers. Ils vendent des enseignes peintes. Linette fait les lettres. Pie fait les fausses, pour ceux qui veulent un nom plus beau que le leur. Ils ne volent plus. Presque plus." },
      { if: { all: [{ present: "pie" }, { not: { present: "linette" } }] }, text: "Pie retourne sur les toits de Pallanche. On le voit, le soir, assis sur la gouttière de Saint-Gilles, à regarder la tour. Il attend quelque chose. Il ne dit pas quoi." },
      { with: "hylas", text: "Hylas retourne aux archives, aveugle, avec sa canne. Il passe ses dernières années à faire lire à voix haute, par les pages, tous les registres de la tour, un par un, pour les entendre une fois avant de mourir." },
      { if: { has: "mordace:fin=pardonne" }, text: "Mordace vit encore dix ans, dans une maison aux volets bleus, au bord de la Lisse. Il n'a plus jamais froid. Il n'écrit plus rien." },
      { if: { has: "mordace:fin=cede" }, text: "Un homme maigre, sans nom, balaie la place aux Clercs chaque matin. Il est très soigneux. Il sourit à tout le monde. Pie passe devant lui tous les jours, et ne s'arrête jamais." },
      { with: "corbe", text: "Corbe retourne aux Combes. Elle apprend à lire à tout le clan, et le clan apprend à chanter les noms sans avoir peur de les voir revenir." },
      { with: "lisandre", text: "Lisandre part pour Corvanne, avec un luth et sa vraie voix. On dit qu'elle chante à la cour de la margrave, et que le chancelier ne manque jamais une soirée." },
      { with: "rodric", text: "Rodric rentre à Hautvent. Il n'y a plus d'armée de chaque côté. Maëlle lui ouvre la porte et lui dit qu'il a mis le temps." },
      { with: "ombeline", text: "Ombeline retourne à son hospice. La faim, dans sa poitrine, s'est tue. Elle ne sait pas si c'est fini, ou si ça dort." },
      { with: "gaspard", text: "Gaspard rallume le four de Sauvelune. Un matin, on le trouve parti, la pelle au clou, les braises couvertes. Il a laissé une miche, encore chaude." },
      { with: "givre", text: "Givre grandit encore un peu, puis plus. Il dort au pied de ton lit, et il mange les petits oublis, et il ronronne. Ça fait tac-tac." },
      { if: { has: "nord:rendu=sauvelune" }, text: "À Sauvelune, à la fête des foins, on fauche le pré la nuit, en chantant, et cette fois on sait ce qu'on fauche, et on chante quand même." },
      { if: { has: "tess:iv" }, text: "Tess t'a écrit. Elle sait lire, maintenant. Sa lettre fait quatre pages, et il y a ton nom à chaque ligne, au cas où." },
      { if: { has: "odon:aide" }, text: "Au moutier des Veilleurs, Frère Odon a fini son livre des arrivées. Il a écrit, sur la dernière page : *Plus personne ne cherche personne.* Puis il a rayé, et réécrit : *Presque.*" },
      { if: { has: "ylva:iv=nom" }, text: "Au clan du Corbeau, une petite fille ne s'assied plus sur la pierre le soir. Elle a appris à graver. Le premier nom qu'elle a gravé, c'est Thora, fille d'Unn." },
      { if: { has: "mathurin:iv" }, text: "Les abeilles de Sauvelune font de nouveau du miel blond. Mathurin jure qu'il n'a jamais été blanc." },
      { if: { has: "liseurs:sauves" }, text: "Aude, la Liseuse, lit encore sur les places de Pallanche, le dimanche. Plus personne ne songe à la pendre. Il y a moins de monde pour l'écouter, et c'est bon signe." },
      { if: { any: [{ has: "thibaut:iv=ysolde" }, { has: "thibaut:iv=grace" }, { has: "thibaut:iv=evade" }] }, text: "Thibaut tisse, à Hautvent, avec sa femme. Il n'a jamais été un bon soldat. C'est un très bon tisserand." },
      { if: { has: "lisse:noms_graves" }, text: "Le mur de la chapelle de Lisse-en-Corvanne porte trois cents noms. On y vient de loin, des deux rives." },
      { if: { has: "iii:gue_paix" }, text: "Au gué aux Saules, sur la Lisse, quelqu'un a planté deux piques en croix, une bleue et une aux couleurs d'Esquarre. Personne ne sait qui. Personne ne les arrache." },
      { if: { has: "givre:terrier" }, text: "Dans les Hautes-Combes, l'hiver suivant, les bergers voient passer des renards blancs, cinq, qui ne laissent pas de traces. Le plus grand s'arrête parfois, au bord du col, et regarde vers le sud, longtemps." },
      { if: { has: "co:renne=ramenee" }, text: "Dans le troupeau du Corbeau, une vieille renne maigre qui s'appelle Brindille mange encore les ceintures." },
      { if: { has: "hy:mur=dit" }, text: "Dans la chapelle de la tour, frère Gauvain a fait effacer au ciseau tous les noms gravés d'avance. Le mur a gardé les traces. Il dit que c'est très bien comme ça." },
      { if: { has: "li:clemence=elle" }, text: "À Brenne, un sergent à la cicatrice au menton a appris à lire, à trente ans, pour pouvoir lire une lettre de six lignes sans qu'on la lui lise." },
      { if: { has: "pi:mouche=recu" }, text: "Mouche a toujours peur des chiens. Elle a adopté le plus gros de Pallanche pour s'y habituer. Ça ne marche pas. Elle le garde quand même." },
      { if: { has: "ys:cheval=garde" }, text: "Sombrevent est mort dans son pré, sous les remparts de Brenne, de vieillesse, à vingt-quatre ans, ce qui ne se voit presque jamais chez un cheval de guerre." },
      { if: { has: "en:mat" }, text: "Tess a toujours le ruban bleu. Elle ne le met jamais. Elle dit qu'il est à la fête des foins, et qu'il attendra la prochaine." },
      { if: { has: "nord:bouches=aude" }, text: "Au col de l'Ourse, le vingt-troisième cairn porte un nom. Depuis, deux autres en ont un. Personne ne sait qui les grave." },
      { if: { has: "sud3:ecuries" }, text: "Au tournoi suivant, à Vasselin, les palefreniers goûtent l'avoine avant de la donner. On ne sait plus très bien pourquoi. C'est devenu la coutume." },
      { if: { has: "iv:nid=pacte" }, text: "Au cairn du col de l'Ourse, les bergers laissent des miettes : un bouton, une cuillère, le nom d'un jour sans importance. Le matin, elles ont disparu. Les enfants du moutier gardent leur nom." },
      { if: { has: "iv:nid_berceaux=sauves" }, text: "Sous le cloître du moutier, sur une table, OBJETS TROUVÉS. Un jour, une femme de Pont-de-Saule a reconnu un gant d'enfant, et s'est assise par terre, et n'a rien pu dire." },
      { if: { has: "iv:patrouille=deux" }, text: "Les frères Mesnil pêchent toujours au gué aux Saules. Ils ont appris chacun cent mots de la langue de l'autre, tous à propos de poissons." },
      { if: { has: "iii:vaure_promis" }, text: "Tu as tenu parole : tu as parlé de Vaure-sur-Lac, une fois, à quelqu'un, un soir. Quelque part dans le blanc, une cloche verte a sonné un coup, sourd, mouillé, avec un quart d'heure de retard." },
      { if: { has: "iii:noces" }, text: "À Bourdonne, deux vieux remontent une rue au bras l'un de l'autre, très lentement. Ils n'ont pas fini. Ils ont tout le temps." },
      { if: { seen: "V_a_rodric_a" }, text: "Tu as gardé la petite cloche qu'il appelait Hautvent. Elle a un joli son. Pas trop fort." },
      { if: { has: "v:dernier=gaspard" }, text: "La dernière miche de Gaspard a été rompue au matin, sur les marches de la tour, pour une femme de la queue qui avait faim, et qui ne savait plus pourquoi." },
      { if: { item: "fil_ellerune" }, text: "Tu as toujours la pelote de laine grise. Les nuits d'hiver, tu la poses sur tes genoux. Elle tient chaud, comme promis." },
      { if: { has: "iv:pontsaule=libere" }, text: "À Pont-de-Saule, un sergent roux garde toujours un pont que personne n'attaque. La baraque grise est devenue un poulailler." },
      { if: { has: "v:carte" }, text: "Dans la salle des cartes de la tour, la grande carte du royaume porte des noms écrits à la main, de travers, de plusieurs écritures. On l'a laissée telle quelle. Les géomètres du roi viennent la recopier, et ne corrigent rien." },
      { if: { has: "ys:recrue=ecuries" }, text: "À Brenne, le garçon des écuries est devenu palefrenier en chef. Il n'a jamais tenu une pique. Il dit que les chevaux, c'est plus difficile." },
      { if: { has: "en:voeu" }, text: "Au fond de la fontaine de Sauvelune, il y a toujours un liard vert, jeté un matin de fête par un enfant qui souhaitait que rien ne change. Tout a changé. On ne l'a pas repêché." },
      { if: { has: "nord:enseigne" }, text: "L'enseigne du Mouton Bleu est revenue au-dessus de la porte de l'auberge de Sauvelune, ou d'une autre auberge, ailleurs. Le mouton est gris. Personne ne le repeint." },
      { if: { has: "sud:bassin=nom" }, text: "À l'Ancre, à Vasselin, la fille de la plonge chante la voix du dessous quand on chante au comptoir. On l'appelle Rossignol. Elle ne demande plus d'où elle vient." },
      { if: { has: "sud:luthier" }, text: "Rue Basse, Maître Fabien vend de nouveau des luths. Ils sont tous finis. Le premier de la série, vernis six fois, pend au-dessus de l'établi, et il n'est pas à vendre." },
      { if: { has: "sud:crieur_noms" }, text: "Le samedi soir, à Vasselin, le crieur des morts dit tous les noms. Quand il en saute un, une fenêtre s'ouvre, et quelqu'un le dit à sa place." },
      { if: { has: "pal:lingerie" }, text: "L'hospice des Cédants lave toujours le linge de la tour, qui n'a plus de greffiers. Sœur Aude dit que les draps sont plus faciles à laver quand personne n'y fait de cauchemars." },
      { if: { has: "iv:jetons=envers" }, text: "Rue des Tonneliers, on vend encore des jetons de bois peints d'une plume. Ils ne font plus entrer nulle part. Les enfants s'en servent pour jouer à la marelle." },
      { if: { has: "iv:bleu=rendu" }, text: "La rivière sort des Teinturiers en trois couleurs, de nouveau. La bande bleue est la plus large." },
      { if: { has: "nord:refuge" }, text: "Au refuge du col de l'Ourse, le livre des passages a repris. Sur une page, entre deux marchands de sel, il y a un corbeau dessiné à l'encre, avec deux flèches. Les passeurs le montrent aux voyageurs. Personne ne sait qui l'a fait." },
      { if: { has: "nord:chien" }, text: "Un grand chien blanc et roux garde toujours le refuge du col. Il est vieux. Il regarde le nord. Les passeurs lui laissent à manger sur le seuil, et l'appellent Brun, et il répond." },
      { if: { has: "nord:echo" }, text: "Au clan du Corbeau, quand un enfant a l'âge, on le mène maintenant à la salle de l'écho, derrière la grande paroi, pour qu'il dise son nom et entende qui répond." },
      { if: { has: "iii:berceuse" }, text: "Il y a une berceuse, dans les vallées, qui a trois couplets. Les mères ne savent pas d'où vient le troisième. Elles le chantent quand même." },
      { if: { has: "hylas:relieur" }, text: "Odilon, le vieux relieur de la tour, ne relie plus de registres. Il relie des cahiers d'écolier, à couverture bleue, pour un sou. Il dit que ça se touche mieux." },
      { if: { has: "ysolde:fers=mauvais" }, text: "À Brenne, Hugues le forgeron garde une paire de menottes cassée net, pendue au-dessus de sa forge. Quand on lui demande ce que c'est, il dit que c'est le plus beau travail de sa vie." },
      { if: { has: "lisandre:ourlet=heloise" }, text: "Dame Héloïse coud toujours des noms dans les ourlets du palais. Dans chaque robe, maintenant, elle en coud deux : celui qu'on lui demande, et le sien, tout petit, dans le pli." },
      { if: { has: "iv:registre=nom" }, text: "Dans le registre du temple de Sauvelune, à la page de l'année de la grêle, il y a deux noms dans une marge, d'une encre qui ne pâlit pas. Les enfants du catéchisme demandent toujours pourquoi l'un des deux est écrit en boucles." },
      { if: { has: "iv:cimetiere" }, text: "Au cimetière de Sauvelune, les noms sur les tombes sont gravés au couteau, de travers, et quelques-uns sont faux. On ne les corrige pas." },
      { if: { any: [{ has: "pie:fiole=volee" }, { has: "pie:fiole=echangee" }] }, text: "Rue des Cardeurs, à Pallanche, un vieil homme parle de sa femme Clotilde à sa petite-fille, tous les soirs. Elle connaît les histoires par cœur. Elle fait semblant que non." },
      { if: { has: "nord:nouveau_ne=garde" }, text: "Au clan du Corbeau, on ne dit plus le nom d'un nouveau-né devant le feu. On le dit à l'oreille, à une seule personne, qui le garde. Ça s'appelle, maintenant, faire une Corbe." },
      { if: { has: "iv:plaques" }, text: "Dans l'armée d'Esquarre, chaque soldat porte maintenant une plaque de plomb au cou. On dit que la coutume vient du camp de Brenne, la veille de la Lisse. Les aumôniers frappent les noms eux-mêmes. Ils n'ont jamais voulu qu'un greffier s'en charge." },
      { if: { has: "iv:infirmerie" }, text: "Le chirurgien du camp de Brenne a écrit un traité. Le premier chapitre s'intitule : *Dire au blessé où il a mal.*" },
      { if: { has: "sud:galere=liberee" }, text: "À Vasselin, il y a maintenant une rue de Corvannais, derrière la halle aux poissons. Ils sont pêcheurs, calfats, cordiers. Le soir, ils chantent une chanson de rameurs, lente, en corvannais, et ils ne la chantent jamais en cadence." },
      { if: { has: "corbe:loup=nomme" }, text: "Sur les crêtes au-dessus du camp du Corbeau, une louve aux yeux jaunes chasse avec ses trois petits devenus grands. Elle ne touche jamais aux rennes. Les chasseurs la saluent de la lance, quand ils la croisent." },
      { if: { has: "corbe:loup=chasse" }, text: "Au camp du Corbeau, il y a trois chiens gris qui ne sont pas des chiens. Ils hurlent les nuits de neige, tournés vers le nord. Personne ne leur dit de se taire." },
      { if: { has: "iv:ossuaire=nourri" }, text: "Sous Saint-Gilles, à Pallanche, quelque chose de blanc dort entre les crânes. Le sacristain lui descend, chaque samedi, un panier de vieux almanachs. Les enfants de la paroisse y ajoutent leurs cahiers de punitions. Il les préfère." },
      { if: { has: "iii:carte_vallee" }, text: "Dans une boîte, au moulin, un carré de vélin sans un mot. Un hameau, un puits, une femme qui chante. Les enfants du meunier demandent souvent ce que c'est. On leur répond que c'est un pays, et qu'il faut le garder." },
      { if: { has: "v:archives=rendues" }, text: "Le printemps qui suit, à Pallanche, on ne parle que de ça : des gens qui se sont réveillés, la nuit de la neige, en se rappelant ce qu'ils avaient vendu. Il y a eu des procès, des larmes, des maisons rendues. Une vieille femme aux mains pâles tient maintenant une échoppe d'écrivain public, rue des Bassins. Elle lit tout ce qu'on lui apporte." },
      { if: { has: "v:archives=brulees" }, text: "Sous la tour des Greffiers, la cave est noire de suie. On n'y range plus rien. Ce qu'on a cédé, à Pallanche, est perdu pour de bon, et personne ne peut plus le réclamer à personne. Certains disent que c'est une injustice. D'autres dorment mieux." },
      { if: { has: "tess:chene" }, text: "À Sauvelune, sur le grand chêne, les noms sont regravés, tous, ceux des vieux, ceux des enfants. L'écorce a commencé à se refermer sur les premiers. Tess repasse le ciseau chaque printemps, avant que l'arbre ne les garde pour lui." },
      { if: { has: "ilse:sauvee" }, text: "Au col de Varre, une petite fille rousse grandit, et ne se souvient pas d'avoir eu de la fièvre. Elle a une poupée de laine grise qu'elle ne prête à personne. Quand on lui demande d'où elle vient, elle dit : d'une dame à cheval." },
      { if: { has: "pie:a_vendu" }, text: "Ce que Pie a vendu au Bureau, l'hiver de la neige blanche, il ne l'a jamais racheté. Il dit que ce n'est pas grave. Il dit qu'il ne s'en souvient pas, justement. Certains soirs, il s'arrête au milieu d'une phrase, et il cherche un mot qui n'existe plus." },
      { if: { has: "anseau:cloches" }, text: "Au clocher de Saint-Aubin, les huit cloches ont toutes un nom, peint en rouge sur le joug. Le vieil Anseau les sonne encore, le dimanche, avec un apprenti qui apprend les noms avant d'apprendre la corde." },
      { if: { has: "hylas:annule" }, text: "Marion Lebas, blanchisseuse, rue des Bassins, a gardé sa nuit. Elle ne la raconte pas. Mais quand une voisine parle d'aller au Bureau, elle pose son battoir, et elle va lui parler, longtemps, à voix basse." },
      { before: "baudoin:iv=dedans", if: { has: "baudoin:sait" }, text: "Frère Baudoin a quitté la Chancellerie au printemps. Il copie des psautiers, dans un moutier de montagne. Dans la marge de chaque psautier, en tout petit, il recopie la même liste de noms, que personne ne lui a demandée." },
      { if: { has: "ylva:sauvee" }, text: "Au clan du Corbeau, une fillette nommée Ylva apprend les chants plus vite que les autres. Elle ne va plus seule dans la neige. Elle y emmène les petits, en rang, en chantant, et elle les ramène tous." },
      { if: { has: "gaspard:chant" }, text: "Le four des crêtes ne refroidit plus. Les bergers qui passent y trouvent toujours des braises, et parfois un pain posé sur la pierre, encore tiède. Personne ne l'a vu cuire." },
      { if: { has: "lisandre:ilan_dit" }, text: "À Corvanne, un jeune homme en manteau bleu chante, dans les cours, une chanson qu'il dit tenir d'une chanteuse d'Esquarre. Il ne la chante jamais deux fois de la même façon. Il dit que c'est elle qui le lui a appris." },
      { if: { has: "aubrac:battu" }, text: "Messire Aubrac chante toujours à la cour. Moins fort. On dit qu'il a pris des leçons, l'hiver dernier, auprès d'un vieux maître de chapelle, et qu'il a recommencé par les gammes, comme un enfant." },
      { if: { has: "nord:nouveau_ne=peint" }, text: "Au clan du Corbeau, un petit garçon nommé Eirik porte un bonnet de renne qu'il refuse d'enlever, même l'été. Sa mère ne lui a jamais dit ce qu'il y a dans la doublure. Elle le lui dira quand il sera grand." },
      { if: { has: "iii:betes=pre" }, text: "Derrière le moulin, le pré qui descend vers le bief ne jaunit plus en été. L'herbe y reste haute et verte, même par la sécheresse. Les bêtes de passage s'y arrêtent d'elles-mêmes, et y restent un moment, sans brouter, la tête levée, comme si elles écoutaient des clochettes." },
      { if: { has: "v:queue=vide" }, text: "Sur le seuil de la tour des Greffiers, il y a un petit tas de jetons de plomb, soudés par le gel, puis par la rouille. Personne ne l'a enlevé. On l'appelle le tas des premiers. Les enfants de Pallanche y posent un caillou, quand ils passent, sans savoir pourquoi on le fait." },
      { if: { has: "v:queue_amants" }, text: "Rue des Bassins, deux maisons qui ne se parlaient plus depuis trois générations ont un petit-fils en commun. Les deux grands-pères se disputent pour savoir à qui il ressemble. Ça les occupe beaucoup." },
      { if: { has: "iii:braise=emportee" }, text: "Dans une niche, au mur du moulin, une braise rouge qui ne s'éteint pas et ne brûle rien. On ne sait plus qui l'a posée là. On sait qu'il ne faut pas y toucher. L'hiver, les enfants viennent tendre les mains au-dessus, et ils disent qu'elle sent la résine." },
      { if: { has: "iii:braise=eteinte" }, text: "Dans la forêt noire, autour d'Ellerune, il paraît qu'une pousse verte est sortie de la cendre. Une seule. On ne sait pas ce que c'est. Une fille et un garçon aux tempes blanches viennent la regarder tous les jours. Ils se disputent pour savoir qui l'arrosera." },
      { if: { has: "pie:grelot" }, text: "Sur les toits de Pallanche, un garçon édenté nommé Grélot se vante d'avoir perdu une course, une seule, dans toute sa vie. Il raconte la gouttière des Ursulines à qui veut l'entendre. Il ne l'a toujours pas prise." },
      { if: { has: "li:perroquet=couvert" }, text: "À la cour, un vieux perroquet gris chante encore, au moindre bruit, *Ô la belle meunière*, et rien d'autre. Personne ne se rappelle ce qu'il disait avant. Une duchesse le nourrit de noisettes, et le trouve charmant." },
      { if: { has: "co:tambour=recousu" }, text: "Le tambour du clan a une couture au milieu de la peau, et un grésillement au milieu du son. Les jeunes du clan disent que c'est un défaut. Les vieux disent que c'est la voix d'avant, qui a appris à boiter." },
      { if: { has: "nord:truites" }, text: "Dans le lac noir, sous la grotte des Corbeaux, il y a toujours des truites noires. Ceux qui en mangent rêvent d'une roue de moulin qui tourne à l'envers. Personne ne comprend ce rêve. Tout le monde le fait." },
      { if: { has: "iii:lac_pere" }, text: "Certaines nuits, tu rêves que tu as trois ans, et que quelqu'un te porte sur ses épaules dans des rues blanches, en chantant faux. Tu te réveilles les mains fermées, comme si tu tenais encore des cheveux." },
      { if: { has: "pim:nom" }, text: "À Sauvelune, on chante encore, aux foins, la chanson de Pim fils de Joris. Elle n'a qu'un couplet. Les enfants en inventent d'autres, chaque été, et Pim, qui a grandi, fait semblant d'en avoir honte." },
      { if: { has: "mathurin:ruches" }, text: "Les ruches de Mathurin ont toujours leurs noms, la Reine-Claude, la Grosse Berthe, la Folle, Saint-Ambroise. Il les apprend à un apprenti, avant de lui apprendre le reste. Il dit que c'est par là qu'on commence." },
      { if: { has: "iv:nid_enfants" }, text: "Au moutier, une petite fille nommée Jehanne joue aux osselets dans le cloître, et dit son nom à tout le monde, à tout propos, à voix haute, comme pour vérifier qu'il tient toujours. Frère Odon ne la reprend jamais." },
      { if: { has: "hy:page=nom" }, text: "Une fillette qui lisait d'une voix plate, sans souffle, a appris à s'arrêter au milieu d'une ligne pour dire son nom. Elle le dit trois fois, comme la première fois. Puis elle reprend sa lecture, à la ligne exacte." },
      { if: { has: "iv:tapisserie=complete" }, text: "À Hautvent, une tapisserie couvre tout un mur de la salle commune : des noms tissés en laine brune, ceux d'Esquarre et ceux de Corvanne, mêlés, sans qu'on sache plus lesquels sont lesquels. Les femmes du village la reprisent chaque hiver, là où les mites passent." },
      { if: { item: "registre_gris" }, text: "Un registre relié de toile grise passe de main en main, à Pallanche, l'année qui suit. Cent noms d'enfants. On les lit aux veillées, à voix haute, lentement. Il en reste une vingtaine que personne n'arrive à prononcer. On les épelle." },
      { if: { has: "iv:foins" }, text: "Aux foins, à Sauvelune, on pend une faux de plus au mur de la grange, affûtée, que personne n'utilise. Joris l'affûte chaque printemps. Quand on lui demande pour qui, il dit : pour la ligne. Il faut que la ligne soit complète." },
      { if: { has: "hylas:berengere=dit" }, text: "Rue des Teinturiers, une vieille femme qui roule les r passe désormais sous le Pont-Neuf, tous les dimanches, lentement, en s'arrêtant au milieu. Elle ne sait pas pourquoi. Elle dit que c'est pour voir si ça fait encore quelque chose. Ça fait encore quelque chose." },
      { if: { has: "pie:sifflet" }, text: "Linette a un sifflet de saule qui siffle faux. Elle ne le prête à personne. Quand elle se perd dans la ville, ce qui lui arrive encore, elle siffle, une fois, et quelque part, sur un toit, quelqu'un siffle en retour." },
      { if: { has: "v:renne" }, text: "Au printemps, un berger du clan du Corbeau a trouvé, au pied des Combes, un vieux renne à la ramure cassée, la robe mitée, une corde coupée autour du cou. Il était mort, couché, la tête tournée vers le nord. Il était presque arrivé. On l'a laissé là. Les corbeaux sont venus. C'est ce qu'il voulait." },
      { if: { has: "iv:violons=appris" }, text: "Les violons de Pont-de-Saule sont revenus à la Fête de Sauvelune. Ils ne jouent qu'un air, la bourrée, encore et encore, toute la nuit. Personne ne s'en plaint. Les autres reviendront peut-être. En attendant, on danse celle-là." },
      { if: { has: "iv:lettre_gardee" }, text: "Dans le coffre d'un écrivain public de Pallanche, il y a une lettre que personne n'a réclamée. Il la relit parfois, le soir, quand il n'y a plus de clients. Il ne la croit pas. Il ne la jette pas non plus. Il a appris à l'aimer comme on aime un conte." },
      { if: { has: "iv:linteaux" }, text: "À Sauvelune, on repeint les noms des maisons chaque printemps, à l'ocre. Celui du moulin est le plus long de la place, avec une petite roue dessous. Personne ne se souvient qui l'a écrit en premier." },
      { if: { has: "sud2:gregoire" }, text: "Maître Grégoire a dirigé les musiciens de Vasselin jusqu'à quatre-vingt-dix ans. Il disait à ses élèves d'entrer un temps trop tôt, une fois dans leur vie, pour voir qui les attendrait." },
      { if: { has: "v:ecole" }, text: "À l'école de la rue des Chanoines, on commence encore chaque matin par la ronde des noms. Les élèves se passent le leur, puis celui du voisin. Le maître ne sait plus pourquoi. Il ne l'a jamais supprimée." },
      { if: { has: "v:lettre_lue" }, text: "L'écrivain public de la place aux Clercs garde dans son coffre une lettre qui n'est adressée à personne. Il attend qu'on revienne lui en dicter la fin." },
      { if: { has: "v:cimetiere" }, text: "Au cimetière de Saint-Gilles, sur certaines tombes, les lettres sont plus fraîches, plus profondes, un peu de travers. Le fossoyeur dit qu'elles ont été regravées par un apprenti. Il n'a jamais eu d'apprenti." },
      { before: "fin:cendres", if: { has: "iii:fil_double" }, text: "Dans certaines fermes d'Esquarre, quand on adopte un enfant, on tresse dans l'ourlet de sa première chemise un fil de lin écru avec un fil de la famille. On dit que c'est une coutume orsane. Les Orsans, eux, disent que c'est une coutume de meunier." },
      { if: { has: "iv:tilleul=sauve" }, text: "Le tilleul de Brenne gêne toujours les manœuvres. Les capitaines successifs ont tous voulu l'abattre. Aucun ne l'a fait." },
      { if: { has: "iv:tilleul=abattu" }, text: "Dans la cour de Brenne, une pierre grise, un cerf, une devise. On l'a laissée où elle était, au pied d'une souche. Ysolde y a fait planter un tilleul neuf, à côté, qui gênera les manœuvres dans cinquante ans." },
      { if: { has: "iv:perrine" }, text: "Après la guerre, deux sœurs, l'une de Brenne, l'autre de Hautvent, se sont disputé chaque automne la meilleure recette du pâté de lièvre. L'une des deux ne se souvenait pas pourquoi elle aimait tant cette dispute." },
      { if: { has: "hylas:dortoir=tu" }, text: "Dans le dortoir des pages, avant que la tour ne ferme, les enfants se disaient leurs noms chaque nuit. Ils racontaient qu'un vieux maître aveugle était monté, un soir, et qu'il avait toussé, et qu'il était reparti. Ils en avaient fait une légende : le greffier qui tousse." },
      { if: { all: [{ quest: "YS_thibaut" }, { has: "thibaut:sort=libre" }] }, text: "Thibaut de Hautvent n'a jamais été inscrit. Il le doit à une capitaine qui a menti une fois dans sa vie, devant un frère gris, et qui ne s'en est jamais confessée." },
      { if: { all: [{ quest: "YS_thibaut" }, { has: "thibaut:sort=livre" }] }, text: "Sur un registre de la Chancellerie, à la page de Hautvent, on peut encore lire le nom d'un soldat de Brenne inscrit avec sa femme, à sa demande. C'est la seule ligne du registre où quelqu'un a demandé." },
      { if: { all: [{ quest: "YS_thibaut" }, { has: "thibaut:sort=repris" }] }, text: "Thibaut a servi dans la compagnie de Brenne jusqu'à la fin de la guerre. Il n'a jamais reparlé de la colonne. Il envoyait chaque mois sa solde à Hautvent, à une femme qui ne savait plus pourquoi elle la recevait." },
      { if: { all: [{ quest: "YS_trou" }, { has: "ysolde:recu" }] }, text: "Ysolde de Brenne a gardé toute sa vie, dans son pourpoint, un reçu de la Chancellerie. Motif : *service de la Couronne.* Prix payé : rien. Elle disait que c'était le papier le plus honnête qu'on lui ait jamais remis." },
      { if: { all: [{ quest: "PI_corneille" }, { has: "corneille:pardonne" }] }, text: "Le vieux Corneille est mort l'hiver suivant, dans la Fosse. On a trouvé six sous dans sa main fermée. Il n'avait pas voulu les dépenser." },
      { if: { all: [{ quest: "PI_corneille" }, { has: "corneille:noye" }] }, text: "On n'a jamais su qui avait noyé le vieux faussaire de la Fosse. Pie, lui, le sait. Il n'a jamais appris à l'oublier, et il n'a jamais essayé." },
      { if: { all: [{ quest: "PI_corneille" }, { has: "corneille:raconte" }] }, text: "Pie a écrit, plus tard, l'histoire d'un vieux faussaire qui s'endormait en racontant ses plus beaux faux. Il ne l'a jamais signée. C'était, disait-il, le seul faux honnête qu'il ait fait." },
      { if: { all: [{ quest: "PI_corneille" }, { has: "corneille:laisse" }] }, text: "Pie n'est jamais redescendu dans la Fosse. Il sait qu'il y a laissé un vieil homme et son vin. Il ne sait pas s'il y a laissé autre chose." },
      { if: { all: [{ quest: "HY_page" }, { has: "linette:nom_dit" }] }, text: "Linette dit toujours qu'elle a appris son nom deux fois : la première, d'un vieux maître aveugle qui lui avait défendu de le répéter ; la seconde, de son frère. La première fois compte autant que l'autre." },
      { if: { all: [{ quest: "HY_noir" }, { has: "hylas:gardien_brise" }] }, text: "Sous la tour, dans la salle ronde, le pupitre du registre noir est resté vide. Ce qui le gardait est en morceaux sur les dalles. On n'a jamais osé les balayer." },
      { if: { all: [{ quest: "CO_lettre" }, { has: "corbe:lettre_lue" }] }, text: "Corbe a gardé la lettre à la cire jaune contre sa peau jusqu'à ce qu'elle tombe en poussière. Elle ne savait pas lire. Elle la savait par cœur, de la voix d'un colporteur de sel." },
      { if: { all: [{ quest: "CO_bran" }, { has: "corbe:voie_bran=oui" }] }, text: "Brann, garde de la porte du Nord, sait qu'il a une sœur. Il ne se souvient pas d'elle. Il a demandé aux marchands de sel de lui apprendre la langue des Combes, mot par mot, et ils rient de son accent." },
      { if: { all: [{ quest: "CO_bran" }, { has: "corbe:voie_bran=non" }] }, text: "À la porte du Nord de Pallanche, il y a un garde roux qui sourit aux femmes du nord quand elles passent, sans savoir pourquoi. L'une d'elles ne lui a jamais rien dit. Elle a eu raison, ou elle a eu tort. Elle passe quand même, chaque printemps." },
      { if: { all: [{ quest: "EN_coffre" }, { has: "enfant:lettre" }] }, text: "La lettre trouvée dans le coffre de Joris, au grenier du moulin, est rangée dans le même coffre, à la même place. Joris n'a jamais demandé qui l'avait lue. Il a seulement remis une clé à la serrure, et il l'a laissée dessus." },
      { if: { all: [{ quest: "II_N_geant" }, { has: "nord:geant=dort" }] }, text: "Au-dessus du moutier des Veilleurs, dans le cirque, un géant de glace dort, la tête sur un rocher. Ombeline monte le voir une fois par an, et lui dit son nom à l'oreille, pour qu'il continue de dormir." },
      { if: { quest: "II_N_chants" }, text: "Dans la grotte des chansons, au bord du lac noir, les chants du Corbeau sont toujours là, dans la pierre. Les enfants du clan y descendent une nuit, la première année où ils ont le droit de chanter seuls." },
      { if: { all: [{ quest: "II_S_tournoi" }, { has: "sud4:grace=nous" }] }, text: "On parle encore à Vasselin du Tournoi de la Paix, et du champion qui avait monté l'escalier de la Tour avec une chanteuse. Les hérauts ne sont pas d'accord sur ses armes." },
      { if: { all: [{ quest: "II_S_lisse" }, { has: "sud4:lisse_lu" }] }, text: "Trois feuilles volées à Vasselin, la nuit du tumulte, ont raconté le pont de Lisse à une capitaine qui l'avait oublié. Elle les a rendues aux archives, après. Signées de sa main, en marge." },
      { if: { all: [{ quest: "IV_Q_thibaut" }, { has: "thibaut:iv=grace" }] }, text: "Thibaut de la compagnie de Brenne a reçu sa grâce de la main de la reine, par un intermédiaire. Il l'a fait encadrer. Elle est accrochée au-dessus du lit qu'il partage avec sa femme, à Hautvent." },
      { if: { all: [{ quest: "IV_Q_thibaut" }, { has: "thibaut:iv=evade" }] }, text: "On dit qu'un homme vit à Hautvent qui n'est ni d'Esquarre ni de Corvanne, et qui a cessé d'avoir un camp. On dit qu'il tisse, et qu'il s'y entend mieux qu'à la pique." },
      { if: { all: [{ quest: "IV_Q_thibaut" }, { has: "thibaut:iv=ysolde" }] }, text: "Sur le pont de Lisse, le matin de la bataille, au premier rang, il y avait un soldat sans arme à côté de la capitaine. Il n'a pas reculé. On ne lui a jamais demandé s'il avait eu peur." },
      { if: { all: [{ quest: "IV_Q_thibaut" }, { has: "thibaut:iv=pendu" }] }, text: "Dans la cour basse de Brenne, il y a une inscription au charbon, sur le mur, à hauteur d'homme : un nom, celui d'une femme, celui d'un village. Personne ne l'efface. On la repasse au charbon chaque printemps." },
      { if: { has: "lisandre:destrier" }, text: "Le destrier gris du vieux roi est mort à Vasselin, dans sa stalle, à trente-deux ans. On dit qu'il levait la tête chaque fois qu'un soldat chantait dans la cour." },
      { if: { has: "pie:battoir" }, text: "Au lavoir des Teinturiers, à la troisième place, une jeune fille aux yeux gris bat le linge avec un battoir marqué d'un J. Elle chante faux. Les vieilles disent que ça lui vient de sa mère." },
      { if: { has: "corbe:tresse" }, text: "Chez le Corbeau, la Bouche n'a plus que six tresses la veille du rite. La septième, une amie la coupe et la garde. On a oublié pourquoi. On continue." },
      { if: { has: "iv:mariette" }, text: "À Pont-de-Saule, la barque du passeur a traversé la Sauve un matin d'automne avec deux vieilles femmes dedans, qui ne se parlaient plus depuis trente ans et qui ne se sont pas tues de toute la traversée." },
      { if: { has: "iv:complainte=vraie" }, text: "On chante encore, dans les foires de la vallée, une complainte de la Neige blanche sans meunier ni berger fou, sur un air lent. Elle n'a pas de rime au dernier couplet. Le marchand qui l'a écrite disait que c'était exprès." },
      { if: { has: "nord:poupee" }, text: "Chez le Corbeau, une poupée de chiffon aux cheveux de laine jaune passe d'enfant en enfant. Sur son tablier, en rouge, un nom que personne au camp n'a jamais porté. On le lui laisse." },
      { if: { has: "nord:lievre=vent" }, text: "Loin à l'est, dans des cirques où le Corbeau ne chasse pas, il y a un clan dont les tentes portent une spirale. On ne sait pas d'où il vient. Lui non plus." },
      { if: { has: "iii:petit_dieu" }, text: "Aux carrefours de la vallée de la Sauve, il arrive qu'on trouve une pomme posée sur une borne, le matin. Personne ne l'a mise. Personne ne la mange." },
      { if: { has: "corbe:ours=chaine" }, text: "Dans les Hautes-Combes, les chasseurs du Corbeau ne tirent jamais sur un ours brun qui porte une cicatrice en croix sur le museau. Il vient parfois rôder près du camp, à la fin de l'été, quand on fait la musique." },
      { if: { has: "corbe:ours=nomme" }, text: "On montre encore, dans les foires du sud, un vieil ours qu'on appelle Hjalti. Son maître prononce mal. L'ours répond quand même." },
      { if: { has: "v:cols" }, text: "À Pallanche, la corporation des Tailleurs coud toujours le nom du client à l'intérieur du col, au point de chaînette, gratis. Les étrangers trouvent ça puéril. Les gens de Pallanche ne discutent pas." },
      { if: { has: "v:jardin" }, text: "Au jardin des simples de la Faculté, cent étiquettes sont d'une écriture d'enfant, appliquée, avec deux l à officinalis. Le jardinier refuse qu'on les repeigne." },
      { if: { has: "iv:prisonnier=rendu" }, text: "Gilles le Roux, de la compagnie de Brenne, a rendu trois sous au vieux Gautier le lendemain du pont. Son nom était gravé sur une plaque, à la chapelle, parmi les morts. On ne l'a pas effacé. Il passe devant chaque dimanche." },
      { if: { has: "iv:tambour" }, text: "Dans l'armée de Corvanne, on apprend encore aux enfants de troupe une batterie qu'on n'apprenait plus : la chamade. On dit qu'un tambour de douze ans l'a jouée, un matin, sur la Lisse, sans ordre. On ne l'a pas puni." },
      { if: { has: "iii:lepreux" }, text: "À la léproserie de Saint-Lazare, hors les murs de Pallanche, on a pris l'habitude, depuis cette année-là, d'appeler chaque malade par son nom quand on sonne pour lui. On ne sait pas qui a commencé." },
      { if: { has: "iii:jouets" }, text: "Sur une étagère, au moulin de Sauvelune, un petit loir de bois dort, roulé en boule, la queue sur le nez. Pim a demandé d'où il venait. On lui a répondu : d'une fenêtre." },
      { if: { has: "ysolde:lettre_pere" }, text: "Ysolde de Brenne a gardé jusqu'à sa mort la lettre de son père, dans son pourpoint, contre sa peau. Elle disait qu'elle avait choisi sa désobéissance. Elle n'a jamais dit laquelle c'était." },
      { if: { has: "v:reclamation" }, text: "Dans les archives de Pallanche, on conserve une réclamation numéro un, déposée la dernière nuit au guichet de l'article neuf. Elle n'a jamais été examinée. Elle n'a jamais été rejetée non plus. On dit qu'elle est toujours en cours." },
      { if: { has: "v:bal" }, text: "À Pallanche, le bal masqué de la rue des Chanoines se donne chaque année, la même nuit. On y entre sous un faux nom. On n'ôte son masque qu'au lever du soleil. Personne ne sait plus d'où vient la règle. Tout le monde la respecte." },
      { if: { has: "v:veuve" }, text: "La Veuve, aux Teinturiers, a rouvert sa boutique. Elle parle de son mari à tous ses clients, longuement, et les clients le connaissent maintenant mieux qu'elle ne l'a connu." },
      { if: { has: "v:cloche" }, text: "À Pallanche, la Bénigne sonne chaque année, la nuit de l'anniversaire, une seule fois. Ceux qui étaient dans la queue lèvent la tête. Ils ne savent pas pourquoi." },
      { if: { has: "v:liseurs" }, text: "Les Liseurs lisent toujours, sous les arcades de la place aux Clercs. On ne les pend plus. On leur apporte des listes." },
      { if: { has: "nord:lignee" }, text: "Au rite de printemps, le vieux Torgal chante les lignées d'une traite. Après Haldis, il chante Sigrun, et il appuie un peu dessus, comme sur une marche qu'on a réparée." },
      { if: { has: "nord:veille_neige" }, text: "Au moutier, un novice a replanté de la veille-neige dans le jardin des simples. Elle pousse mal, à l'envers, et sent le pain chaud." },
      { if: { has: "sud:theatre=joue" }, text: "Les Gonfaloniers jouent toujours *La Reine des Marais*. Dame Orane a repris le rôle. Au quatrième acte, elle joue comme une autre, et on dit que c'est mieux qu'avant." },
      { if: { any: [{ has: "sud:phare=sauve" }, { has: "sud:phare=tenu" }] }, text: "Le phare de la Pointe brûle chaque nuit. Yvon, qui ne boit plus que de l'eau, monte les cent douze marches en les comptant à voix haute." },
      { if: { has: "sud:fioles=brisees" }, text: "Quai des Cordiers, la verrerie vend des carafes et des verres à pied. Plus une seule fiole." },
      { if: { has: "sud:fioles=rendu" }, text: "Une actrice de Vasselin mouille encore, chaque matin, les cheveux d'un fils qui n'est plus là. Elle dit que c'est la seule chose qu'elle ait jamais regretté de vendre." },
      { if: { has: "brenne:cerf" }, text: "Au-dessus de la porte de Brenne, on a regravé un cerf. Les enfants du bourg demandent ce qu'il fait là. Personne ne leur répond la même chose." },
      { if: { has: "pie:matrice" }, text: "La matrice de Corneille n'a plus jamais servi. Pie la garde dans une poche cousue, et la sort parfois, le soir, pour la regarder sans rien signer." },
      { if: { has: "marion:iv=sait" }, text: "Rue des Bassins, une blanchisseuse raconte à qui veut l'entendre qu'un vieux greffier lui a rendu une nuit. On ne la croit pas. Elle s'en moque." },
      { if: { has: "lisandre:chanson_lisse" }, text: "La chanson de Lisse a désormais sept couplets. Le septième, on le chante des deux côtés de la rivière, et chaque rive jure qu'il est d'elle." },
      { if: { has: "sansnom:ilse" }, text: "Ilse a appris à ton frère à faire des ricochets. Il n'en réussit jamais plus de deux. Elle dit que c'est déjà beaucoup, pour quelqu'un qui n'avait pas d'enfance." },
      { if: { any: [{ has: "gaspard:pain_lisse" }, { has: "gaspard:pain_camp" }] }, text: "Gaspard a reconstruit un four, de pierre cette fois. Le premier pain, il l'a rompu sans rien dire et l'a laissé refroidir sur le rebord, pour Berthe." },
      { if: { has: "rodric:cloches" }, text: "Rodric a rendu ses cloches aux familles. Il marche plus droit sans elles, et il s'en plaint." },
      { if: { has: "baudoin:iv=dedans" }, text: "Frère Baudoin est resté à la Chancellerie. On dit qu'il a l'écriture la plus lisible de la tour, et qu'il refuse d'écrire certaines choses." },
      "Ici s'achèvent Les Cendres de l'Hiver.",
    ],
    end: true,
    choices: [{ label: "Recommencer", restart: true, to: "C_six" }] }),
};
